1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_LEVEL = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  staff: 800,
63	  potion: 400,
64	  rune: 250,
65	  moonstone: 250,
66	};
67	
68	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
69	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
70	
71	const COMPONENT_BLOCK_SIZE = 3;
72	const COMPONENT_BLOCK_PREMIUM = 60;
73	
74	const countsByType = (items: Item[]): Map<string, number> =>
75	  items.reduce(
76	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
77	    new Map<string, number>(),
78	  );
79	
80	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
81	
82	/** Exactly three alike components form a building block, priced at a flat rate. */
83	const basePremiumForAlikeItems = (type: string, count: number): number =>
84	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
85	    ? COMPONENT_BLOCK_PREMIUM
86	    : count * BASE_PREMIUMS[type];
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  [...countsByType(items)].reduce(
90	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
91	    0,
92	  );
93	
94	/**
95	 * Modifiers are rates on a base premium, never on each other, so each one is
96	 * measured against the same base and the results are summed.
97	 */
98	const amountOf = (rate: number, basePremium: number): number => rate * basePremium;
99	
100	/** Item-specific surcharge rates stack additively on the item's own base premium. */
101	const surchargeRateFor = (item: Item): number =>
102	  (item.cursed ? CURSE_SURCHARGE : 0) +
103	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0);
104	
105	/** Item-specific surcharges are rates on the affected item's own base premium. */
106	const itemSurchargeAmount = (items: Item[]): number =>
107	  items.reduce(
108	    (total, item) => total + amountOf(surchargeRateFor(item), BASE_PREMIUMS[item.type]),
109	    0,
110	  );
111	
112	/**
113	 * The facts a policy-wide rate is measured against. Rates key on different
114	 * things — loyalty on the customer's history, the assessment/follow-up rate on
115	 * where the quote falls in the scenario — so they travel together as context.
116	 */
117	interface PolicyContext {
118	  customer: Customer;
119	  /** Zero-based position of this quote among the scenario's quotes. */
120	  quoteOrdinal: number;
121	}
122	
123	/** Policy-wide rates apply to the policy base premium; discounts are negative. */
124	const policyRateFor = ({ customer, quoteOrdinal }: PolicyContext): number =>
125	  INITIAL_ASSESSMENT_SURCHARGE +
126	  (customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0) +
127	  (quoteOrdinal > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0);
128	
129	const quote = (step: QuoteStep, policy: PolicyContext): StepResult => {
130	  const base = policyBasePremium(step.items);
131	  const modifiers = itemSurchargeAmount(step.items) + amountOf(policyRateFor(policy), base);
132	  return {
133	    premium: roundPremiumInMHPCOFavour(base + modifiers + PROCESSING_FEE),
134	  };
135	};
136	
137	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
138	
139	const DEDUCTIBLE_PER_DAMAGE = 100;
140	const CAP_MULTIPLIER = 2;
141	
142	/** Payouts round down: fractions of a Gold piece stay with the MHPCO. */
143	const roundPayoutInMHPCOFavour = (amount: number): number => Math.floor(amount);
144	
145	const SEVERE_ENCHANTMENT_LEVEL = 8;
146	const SEVERE_ENCHANTMENT_REIMBURSEMENT = 0.5;
147	const FULL_REIMBURSEMENT = 1;
148	
149	/** Damage to a heavily enchanted item is reimbursed at half its amount. */
150	const reimbursementRateFor = (item: Item): number =>
151	  (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL
152	    ? SEVERE_ENCHANTMENT_REIMBURSEMENT
153	    : FULL_REIMBURSEMENT;
154	
155	const itemDamagedBy = (damage: Damage, items: Item[]): Item => {
156	  const item = items.find((candidate) => candidate.type === damage.itemType);
157	  if (!item) throw new Error(`Policy does not cover a ${damage.itemType}`);
158	  return item;
159	};
160	
161	/** A policy issued by a quote step, tracking how much of its cap remains. */
162	interface Policy {
163	  items: Item[];
164	  remainingCap: number;
165	}
166	
167	const insuranceSum = (items: Item[]): number =>
168	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
169	
170	const openPolicy = (items: Item[]): Policy => ({
171	  items,
172	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
173	});
174	
175	/** Every damage entry carries its own deductible, applied after any clause. */
176	const payoutForDamage = (damage: Damage, item: Item): number =>
177	  amountOf(reimbursementRateFor(item), damage.amount) - DEDUCTIBLE_PER_DAMAGE;
178	
179	const desiredPayout = (damages: Damage[], items: Item[]): number =>
180	  damages.reduce(
181	    (total, damage) =>
182	      total + payoutForDamage(damage, itemDamagedBy(damage, items)),
183	    0,
184	  );
185	
186	/**
187	 * Settling a claim pays out and draws the policy's cap down by that amount, so
188	 * it yields both the result and the policy as it stands afterwards.
189	 */
190	const settleClaim = (
191	  step: ClaimStep,
192	  policy: Policy,
193	): { result: StepResult; policy: Policy } => {
194	  const payout = roundPayoutInMHPCOFavour(
195	    desiredPayout(step.incident.damages, policy.items),
196	  );
197	  const remainingCap = policy.remainingCap - payout;
198	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
199	};
200	
201	export const runScenario = (scenario: Scenario): ScenarioResult => {
202	  /** A claim names its policy by the index of the quote step that opened it. */
203	  const policiesByQuoteStep = new Map<number, Policy>();
204	  const results = scenario.steps.map((step, index) => {
205	    if (isQuote(step)) {
206	      const context = {
207	        customer: scenario.customer,
208	        quoteOrdinal: policiesByQuoteStep.size,
209	      };
210	      policiesByQuoteStep.set(index, openPolicy(step.items));
211	      return quote(step, context);
212	    }
213	    const policy = policiesByQuoteStep.get(step.policy);
214	    if (!policy) throw new Error(`No policy created by step ${step.policy}`);
215	    const settled = settleClaim(step, policy);
216	    policiesByQuoteStep.set(step.policy, settled.policy);
217	    return settled.result;
218	  });
219	  return { results };
220	};
